public sealed class ManagementCompanyRequestConfiguration:IEntityTypeConfiguration<ManagementCompanyRequest>
{
 public void Configure(EntityTypeBuilder<ManagementCompanyRequest>b){b.ToTable("management_company_requests");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasColumnName("id");b.Property(x=>x.FriendlyIdentifier).HasColumnName("friendly_identifier").HasMaxLength(16).IsRequired();b.Property(x=>x.CondominiumId).HasColumnName("condominium_id");b.Property(x=>x.ManagementCompanyId).HasColumnName("management_company_id");b.Property(x=>x.CategoryId).HasColumnName("category_id");b.Property(x=>x.CreatedByUserId).HasColumnName("created_by_user_id");b.Property(x=>x.Type).HasColumnName("type").HasConversion<string>().HasMaxLength(30);b.Property(x=>x.Status).HasColumnName("status").HasConversion<string>().HasMaxLength(30);b.Property(x=>x.ConcurrencyStamp).HasColumnName("concurrency_stamp").IsConcurrencyToken();b.Property(x=>x.AcknowledgedByUserId).HasColumnName("acknowledged_by_user_id");b.Property(x=>x.AcknowledgedAt).HasColumnName("acknowledged_at");b.Property(x=>x.CompletedByUserId).HasColumnName("completed_by_user_id");b.Property(x=>x.CompletedAt).HasColumnName("completed_at");b.Property(x=>x.CancelledByUserId).HasColumnName("cancelled_by_user_id");b.Property(x=>x.CancelledAt).HasColumnName("cancelled_at");b.Property(x=>x.CancellationReason).HasColumnName("cancellation_reason").HasMaxLength(500);b.Property(x=>x.CreatedAt).HasColumnName("created_at");b.Property(x=>x.UpdatedAt).HasColumnName("updated_at");
 b.HasOne<Condominium>().WithMany().HasForeignKey(x=>x.CondominiumId).OnDelete(DeleteBehavior.Restrict);b.HasOne<ManagementCompany>().WithMany().HasForeignKey(x=>x.ManagementCompanyId).OnDelete(DeleteBehavior.Restrict);b.HasOne<ManagementCompanyRequestCategory>().WithMany().HasForeignKey(x=>x.CategoryId).OnDelete(DeleteBehavior.Restrict);b.HasOne<ApplicationUser>().WithMany().HasForeignKey(x=>x.CreatedByUserId).OnDelete(DeleteBehavior.Restrict);b.HasOne<ApplicationUser>().WithMany().HasForeignKey(x=>x.AcknowledgedByUserId).OnDelete(DeleteBehavior.Restrict);b.HasOne<ApplicationUser>().WithMany().HasForeignKey(x=>x.CompletedByUserId).OnDelete(DeleteBehavior.Restrict);b.HasOne<ApplicationUser>().WithMany().HasForeignKey(x=>x.CancelledByUserId).OnDelete(DeleteBehavior.Restrict);
 b.HasIndex(x=>x.FriendlyIdentifier).IsUnique().HasDatabaseName("ux_management_company_requests_friendly_identifier");b.HasIndex(x=>new{x.ManagementCompanyId,x.CategoryId,x.Status,x.UpdatedAt});b.HasIndex(x=>new{x.CondominiumId,x.Status,x.UpdatedAt});b.HasIndex(x=>x.CreatedAt);}
}
