t>(x=>x.RequestId).OnDelete(DeleteBehavior.Restrict);b.HasOne<ApplicationUser>().WithMany().HasForeignKey(x=>x.BeneficiaryUserId).OnDelete(DeleteBehavior.Restrict);}}
